    id: "gmat-rc-0001", section: "verbal", type: "reading-comprehension",
    difficulty: "Medium", topic: "Reading Comprehension · social science",
    explanation: "Each sub-question is explained individually below.",
    passage:
      "For much of the twentieth century, economists treated the household as a single decision-making unit, as though a family shared one set of preferences. Beginning in the 1980s, however, a number of researchers challenged this 'unitary' model. They argued that households are better understood as arenas of negotiation, in which members with distinct preferences bargain over how resources are allocated.\n\nEvidence for this 'collective' view came from studies of how income affected spending. When income controlled by women rose relative to income controlled by men, spending patterns shifted — for instance, toward children's health and education. Under a strict unitary model, the source of a household's income should not affect how it is spent, since the household supposedly pools everything and spends according to shared priorities. The observed shifts therefore undermined the unitary assumption.\n\nCritics of the collective model concede that it fits the data better but note that it is harder to apply, since it requires information about each member's preferences and bargaining power — information that is often unavailable. The debate thus illustrates a recurring tension in economics between models that are tractable and models that are realistic.",
