    id: "gmat-rc-0002", section: "verbal", type: "reading-comprehension",
    difficulty: "Hard", topic: "Reading Comprehension · science",
    explanation: "Each sub-question is explained individually below.",
    passage:
      "Coral reefs occupy less than one percent of the ocean floor, yet they support roughly a quarter of all marine species. This disproportionate richness has long puzzled ecologists, because the waters surrounding many reefs are strikingly low in the dissolved nutrients that usually fuel biological productivity. The apparent paradox — abundant life in nutrient-poor water — is sometimes called 'Darwin's paradox,' after the naturalist who first remarked on it.\n\nThe leading resolution centres on efficiency rather than supply. Reef organisms recycle nutrients with unusual thoroughness: waste produced by one organism is rapidly absorbed by another, so the same atoms of nitrogen and phosphorus cycle through the community many times before being lost. Symbiotic relationships are central to this thrift. Reef-building corals, for example, host photosynthetic algae within their tissues; the algae supply the coral with energy, and the coral supplies the algae with nutrients and shelter.\n\nThis tight coupling, however, is also a vulnerability. When water temperatures rise even slightly above the normal maximum, corals expel their algae — a process known as bleaching — and lose their principal energy source. If the stress is brief, corals may recover; if it is prolonged, they die. Because the entire reef economy rests on this partnership, the loss of the algae can cascade through the community, dismantling in months an ecosystem that took millennia to assemble.",
