          "The passage calls the partnership central to the reef's thrift yet a vulnerability under heat stress — both at once.",
          "The relationship benefits the coral (energy) as well as the algae, so it is not one-sided harm.",
          "The symbiosis is described as central to productivity, not irrelevant.",
