    "The rapid proliferation of social media platforms over the past two decades has fundamentally altered how information spreads through society. Where news once filtered through editors and fact-checkers before reaching the public, it now travels directly from source to audience within seconds. Proponents argue that this democratises information, giving voice to those previously excluded from mainstream discourse. Critics, however, contend that the removal of editorial gatekeeping has made it far easier for misinformation to spread unchecked.\n\nResearch into the spread of false information online suggests that false stories spread faster and more broadly than true ones. One widely cited study found that false news reached its first 1,500 users approximately six times faster than accurate stories did. The researchers attributed this partly to the novelty effect: inaccurate stories tend to be more surprising and emotionally engaging, making users more likely to share them.\n\nPlatforms have responded by introducing fact-checking labels, algorithmic downranking of disputed content, and partnerships with independent verification organisations. Critics of these measures argue that they are insufficient and inconsistently applied, while others worry that platform-level content moderation gives private companies too much power over public discourse. The debate reflects a broader tension between the free flow of information and the societal costs of unchecked misinformation.",
