        "The passage attributes speed to user behaviour, not deliberate platform amplification.",
        "Correct: the passage explicitly cites the novelty effect — false stories are more surprising and emotionally engaging, driving shares.",
        "Fact-checker speed is not the explanation given in the passage.",
        "Gatekeeping bias is not mentioned as a cause of differential spread.",
