    "Nurse scheduling is an operational concern, not the core assumption behind the readmission reduction.",
    "Correct: the calls reduce readmissions only if many readmissions stem from problems a call could catch in time — without this, the calls won't lower readmissions.",
    "Phone access is a practical prerequisite but not the central causal assumption.",
    "How the hospital compares to the national average is irrelevant to whether the plan works.",
    "Relative cost is a separate consideration from whether readmissions actually fall.",
